/**
 * GET /api/jobs/[jobId]/preview
 *
 * Lists rasterised preview images (preview-1.jpg, preview-2.jpg, ...)
 * generated by lib/docxConvert.ts and returns short-lived signed URLs
 * served through the existing /api/jobs/[jobId]/file route.
 *
 * Auth: NextAuth session + ownership check (job.adminId == current admin).
 *
 * Response:
 *   {
 *     ready: boolean,           // true when at least one preview-*.jpg exists
 *     pages: string[],          // signed URLs in numerical page order
 *     totalPages: number,       // pages.length
 *     status: "converting" | "ready" | "unsupported"
 *   }
 *
 * The admin job page polls this endpoint every ~2s until ready, then
 * stops. If LibreOffice / pdftoppm aren't installed on the server,
 * pages stays empty forever — the UI surfaces a timeout after a few
 * polls and falls back to a "preview unavailable" state.
 */

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import path from "path";
import { existsSync, readdirSync } from "fs";
import prisma from "@/lib/prisma";
import { getJobDir, generateFileToken } from "@/lib/storage";

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ jobId: string }> },
) {
  const { jobId } = await params;

  // 1. Session auth
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  // 2. Resolve admin record + ownership check.
  const admin = await prisma.admin.findUnique({
    where: { userId: session.user.id },
  });
  if (!admin) {
    return NextResponse.json({ error: "Not an admin" }, { status: 403 });
  }

  const job = await prisma.job.findUnique({ where: { id: jobId } });
  if (!job) {
    return NextResponse.json({ error: "Job not found" }, { status: 404 });
  }
  if (job.adminId !== admin.id) {
    return NextResponse.json(
      { error: "Job belongs to another admin" },
      { status: 403 },
    );
  }

  // 3. Encrypted jobs are never converted server-side — we don't decrypt.
  if (job.isEncrypted) {
    return NextResponse.json({
      ready: false,
      pages: [],
      totalPages: 0,
      status: "unsupported",
    });
  }

  // 4. List preview-*.jpg files in the job dir.
  const jobDir = getJobDir(jobId);
  if (!existsSync(jobDir)) {
    return NextResponse.json({
      ready: false,
      pages: [],
      totalPages: 0,
      status: "converting",
    });
  }

  let entries: string[] = [];
  try {
    entries = readdirSync(jobDir);
  } catch {
    return NextResponse.json({
      ready: false,
      pages: [],
      totalPages: 0,
      status: "converting",
    });
  }

  // pdftoppm names files like "preview-1.jpg" / "preview-12.jpg".
  // Lexical sort breaks at 10. Sort numerically by extracted index.
  const pageRegex = /^preview-(\d+)\.jpe?g$/i;
  const pageFiles = entries
    .filter((f) => pageRegex.test(f))
    .map((f) => ({
      name: f,
      idx: parseInt(f.match(pageRegex)![1], 10),
    }))
    .sort((a, b) => a.idx - b.idx)
    .map((p) => p.name);

  if (pageFiles.length === 0) {
    return NextResponse.json({
      ready: false,
      pages: [],
      totalPages: 0,
      status: "converting",
    });
  }

  // 5. Sign each preview image so the existing file API can serve it.
  // Tokens are short-lived (default 120s); the admin UI re-fetches this
  // endpoint when it needs fresh tokens.
  const pages = pageFiles.map((name) => {
    const token = generateFileToken(jobId, name, 600); // 10 min window
    const qs = new URLSearchParams({ name, token }).toString();
    return `/api/jobs/${jobId}/file?${qs}`;
  });

  return NextResponse.json(
    {
      ready: true,
      pages,
      totalPages: pages.length,
      status: "ready",
    },
    {
      headers: {
        "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      },
    },
  );
}
